package com.mamtrex.hospital.pharmacy;
import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="drugs") public class Drug extends BaseEntity { private String code; private String genericName; private String brandName; private String strength; private String stockQuantity; protected Drug(){} public Drug(String code, String genericName, String brandName, String strength, String stockQuantity){this.code=code; this.genericName=genericName; this.brandName=brandName; this.strength=strength; this.stockQuantity=stockQuantity;} public String getCode(){return code;} public String getGenericName(){return genericName;} public String getBrandName(){return brandName;} public String getStrength(){return strength;} public String getStockQuantity(){return stockQuantity;} }
